from fastapi import APIRouter, Depends, HTTPException
from temporalio.client import Client

router = APIRouter(prefix="/deployments/workflows")

@router.get("/{workflow_id}/pipeline-secrets")
async def query_pipeline_secrets(
    workflow_id: str,
    temporal_client: Client = Depends(get_temporal_client),
    developer: DevUser = Depends(get_developer_user),
    pipeline_svc: PipelineService = Depends(get_pipeline_service)
):
    pipeline = await pipeline_svc.get_pipeline_for_workflow(workflow_id)
    if not pipeline:
        raise HTTPException(status_code=404, detail="Deployment pipeline not found")
    if pipeline.project_id not in developer.admin_project_ids and not developer.is_devops_lead:
        raise HTTPException(status_code=403, detail="Forbidden: developer lacks admin permissions to inspect secrets for this pipeline")

    try:
        handle = temporal_client.get_workflow_handle(workflow_id)
        secrets = await handle.query("get_injected_secrets")
        return {"workflow_id": workflow_id, "injected_environment": secrets}
    except Exception:
        raise HTTPException(status_code=404, detail="Workflow not found or does not support secrets query")
